data.query:
query GetShipmentCount($id: String!) {
  integratedCarrierShipment(where: { id: { _eq: $id } }, first: 1, orderBy: null) {
    total
  }
}

data.transform:
(
  $isNilOrEmpty(Shipper_Key)
    ? $throw("Shipper_Key must be provided as a parameter to the flow");

  {
    "parameters": $,
    "integratedCarrierShipmentId": "plex-" & Shipper_Key
  }
)

data.mutation:
mutation CreateIntegratedShipment($create: IntegratedCarrierShipmentCreateInput!) {
  createIntegratedCarrierShipment(payload: { create: $create }) {
    id
  }
}

data.transform:
$merge([
  {
    "number": $state.context.shipperData.Packing_List.Shipper_No,
    /* There's no way to directly link to a shipper form in Classic. */
    "externalReferenceUrl": "https://cloud.plex.com/Shipping/StandardShipping/ViewShipperForm?ShipperKey=" & $state.context.parameters.Shipper_Key,
    "shipTo": {
      "name": $state.context.shipperData.Ship_To.Name,
      "phoneNumber": $state.context.shipperData.Ship_To.Phone,
      "residential": $state.context.shipperData.Ship_To.Residential
    },
    "shipToAddress": {
      "lines": $split($state.context.shipperData.Ship_To.Address, "\n"),
      "city": $state.context.shipperData.Ship_To.City,
      "state": $state.context.shipperData.Ship_To.State,
      "postalCode": $state.context.shipperData.Ship_To.Zip,
      "country": $state.context.shipperData.Ship_To.Country
    },
    "shipFrom": {
      "name": $state.context.shipperData.Packing_List.Ship_From_Customer_Name,
      "phoneNumber": $state.context.shipperData.Packing_List.Ship_From_Phone
    },
    "shipFromAddress": {
      "lines": $split($state.context.shipperData.Packing_List.Ship_From_Address, "\n"),
      "city": $state.context.shipperData.Packing_List.Ship_From_City,
      "state": $state.context.shipperData.Packing_List.Ship_From_State,
      "postalCode": $state.context.shipperData.Packing_List.Ship_From_Zip,
      "country": $state.context.shipperData.Packing_List.Ship_From_Country
    },
    "packageDefinitions": [$state.context.shipperData.Packages.{
      "referenceNumbers": [{
        "type": "purchaseOrderNumber",
        "value": $state.context.shipperData.Shipper.PO_No
      }, {
        "type": "serialNumber",
        "value": Serial_No
      }],
      "length": Length != '0' ? {
        "value": $number(Length),
        "unit": {
          "id": "inches",
          "label": "in",
          "code": "in"
        }
      },
      "width": Width != '0' ? {
        "value": $number(Width),
        "unit": {
          "id": "inches",
          "label": "in",
          "code": "in"
        }
      },
      "height": Height != '0' ? {
        "value": $number(Height),
        "unit": {
          "id": "inches",
          "label": "in",
          "code": "in"
        }
      },
      "weight": Weight != '0' ? {
        "value": $number(Weight),
        "unit": {
          "id": "pounds",
          "label": "lbs",
          "code": "lbs"
        }
      }
    }],
    /* Theoretically driven by logic based on customer/address/etc. */
    "integratedCarrierId": null,
    "integratedCarrierServiceId": null,
    "integratedCarrierBillToAccountId": null,
    "integratedCarrierConnectionConfigurationId": null
  },
  $
])

data.query:
query GetShipmentInfo($id: String!) {
  integratedCarrierShipment(where: { id: { _eq: $id } }, first: 1, orderBy: null) {
    edges {
      node {
        id
        number
        description
        shipTo
        shipToAddress {
          lines
          city
          state
          postalCode
          country
        }
        shipFrom
        shipFromAddress {
          lines
          city
          state
          postalCode
          country
        }
        packageDefinitions
        trackingNumber
        packageLabels
        totalCharges {
          value
          unit {
            id
            code
          }
        }
        integratedCarrierConnectionConfiguration {
          id
          name
        }
        integratedCarrierService {
          id
          name
        }
        integratedCarrierBillToAccount {
          id
          name
        }
        integratedCarrier {
          id
          name          
        }
      }
    }
  }
}

query PlexConnection($pcn: JSON!) {
  connection(where: { 
    	connectorId: { _in: [
        "464e9c3f-dd6c-47af-8078-cda1ff25e966", 
        "72974b11-897f-47bd-896d-133962ef7bbb"
      ] }
    	_or: [ 
        { options: { _eq: { path: "PCN", value: $pcn } } }, 
        { options: { _isNull: { path: "PCN", value: true } } } 
  	  ]
    	_not: {
        url: {
          _contains: "test"
        }
      }
  	}) {
    total
    edges {
      node {
        id
        name
        connectorId
      }
    }
  }
}

data.transform:
(
  total > 1
    ? $throw("Multiple valid Plex connections found; ensure connections have PCN configured and PCN is passed from extension");

  total = 0
    ? $throw("No valid Plex connection found");

  {
    "connection": connection.edges[0].node
      ~> | $ | {
        "classic": connectorId = "464e9c3f-dd6c-47af-8078-cda1ff25e966"
      } |
  }
)

/* Datasource is not registered in UX! */
$state.context.connection.classic
  ? $integrate({
      "result": {
        "connectionId": $state.context.connection.id,
        "payload": [
          {
            "datasourceKey": $state.context.connection.classic
              ? 47190
              : "NOT REGISTERED",
            "datasourceName": "sproc283025_Integrated_Shipping_Packages_Get",
            "parameters": {
              "Shipper_Key": $state.context.parameters.Shipper_Key
            }
          }
        ]
      }
    }).result.Rows
  : []

{
  "integratedCarrierId": "ckmwk8fv600010i4sgvetax0g", /* UPS */
  "integratedCarrierServiceId": "ckmxv51ra000s0j7j2o052mzz", /* Ground */
  "integratedCarrierBillToAccountId": "ckmxu72l7003b0i7171sm2uz6", /* Cumulus UPS */
  "integratedCarrierConnectionConfigurationId": "ckmxyiwta000q0i2zba479uqe" /* Cumulus UPS */
}

